<?php

declare(strict_types=1);

namespace App\Policies;

use App\Models\Event;
use Illuminate\Auth\Access\HandlesAuthorization;
use Illuminate\Foundation\Auth\User as AuthUser;

/**
 * Filament Shield policy for Event. Generated by `php artisan shield:generate`;
 * each ability maps to a "{Action}:Event" permission seeded by RoleSeeder.
 * super_admin bypasses these checks (Gate::before in Shield).
 *
 * Regenerating policies with shield:generate may overwrite these docblocks.
 */
class EventPolicy
{
    use HandlesAuthorization;

    /**
     * Determine whether the admin may list Event records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "ViewAny:Event" permission.
     */
    public function viewAny(AuthUser $authUser): bool
    {
        return $authUser->can('ViewAny:Event');
    }

    /**
     * Determine whether the admin may view one Event record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Event  $event  The record being authorized.
     * @return bool True when the admin holds the "View:Event" permission.
     */
    public function view(AuthUser $authUser, Event $event): bool
    {
        return $authUser->can('View:Event');
    }

    /**
     * Determine whether the admin may create Event records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "Create:Event" permission.
     */
    public function create(AuthUser $authUser): bool
    {
        return $authUser->can('Create:Event');
    }

    /**
     * Determine whether the admin may edit a Event record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Event  $event  The record being authorized.
     * @return bool True when the admin holds the "Update:Event" permission.
     */
    public function update(AuthUser $authUser, Event $event): bool
    {
        return $authUser->can('Update:Event');
    }

    /**
     * Determine whether the admin may delete one Event record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Event  $event  The record being authorized.
     * @return bool True when the admin holds the "Delete:Event" permission.
     */
    public function delete(AuthUser $authUser, Event $event): bool
    {
        return $authUser->can('Delete:Event');
    }

    /**
     * Determine whether the admin may bulk delete Event records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "DeleteAny:Event" permission.
     */
    public function deleteAny(AuthUser $authUser): bool
    {
        return $authUser->can('DeleteAny:Event');
    }

    /**
     * Determine whether the admin may restore one soft-deleted Event record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Event  $event  The record being authorized.
     * @return bool True when the admin holds the "Restore:Event" permission.
     */
    public function restore(AuthUser $authUser, Event $event): bool
    {
        return $authUser->can('Restore:Event');
    }

    /**
     * Determine whether the admin may permanently delete one Event record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Event  $event  The record being authorized.
     * @return bool True when the admin holds the "ForceDelete:Event" permission.
     */
    public function forceDelete(AuthUser $authUser, Event $event): bool
    {
        return $authUser->can('ForceDelete:Event');
    }

    /**
     * Determine whether the admin may permanently bulk delete Event records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "ForceDeleteAny:Event" permission.
     */
    public function forceDeleteAny(AuthUser $authUser): bool
    {
        return $authUser->can('ForceDeleteAny:Event');
    }

    /**
     * Determine whether the admin may bulk restore soft-deleted Event records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "RestoreAny:Event" permission.
     */
    public function restoreAny(AuthUser $authUser): bool
    {
        return $authUser->can('RestoreAny:Event');
    }

    /**
     * Determine whether the admin may duplicate a Event record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Event  $event  The record being authorized.
     * @return bool True when the admin holds the "Replicate:Event" permission.
     */
    public function replicate(AuthUser $authUser, Event $event): bool
    {
        return $authUser->can('Replicate:Event');
    }

    /**
     * Determine whether the admin may reorder Event records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "Reorder:Event" permission.
     */
    public function reorder(AuthUser $authUser): bool
    {
        return $authUser->can('Reorder:Event');
    }
}
